  // =====================================================================
  const WEEKS = [{ n: 5, t: 'Неделя 5 · брокеры' }, { n: 6, t: 'Неделя 6 · архитектура' }, { n: 7, t: 'Неделя 7 · надёжность' }, { n: 8, t: 'Неделя 8 · системный дизайн' }];
  const NODES = [
    { id: 'kafka', w: 5, t: 'Kafka для доменных событий', d: 'Топики puls.*.events.v1: журнал, который читают многие потребители, каждый своей группой; можно перечитать за 7 дней.', why: 'На событие «записался» реагируют 6 потребителей, событий ~2 млн в день.', price: 'Ещё одна система в эксплуатации; доставка at-least-once.', st: 'mq-why' },
    { id: 'rabbit', w: 5, t: 'RabbitMQ для уведомлений', d: 'Очередь задач «отправь пуш или SMS»: подтверждение каждого сообщения, отложенный повтор, приоритеты, DLQ.', why: 'До 300 тыс. пушей за вечер воскресенья; код входа важнее рекламы.', price: 'Два брокера — две модели в голове и вдвое больше работы SRE.', st: 'mq-kafka' },
    { id: 'key', w: 5, t: 'Ключ партиции class_session_id', d: 'Все события одного занятия попадают в одну партицию и читаются по порядку.', why: 'Инцидент 2: с ключом client_id «лист ожидания» записал человека на отменённое занятие.', price: 'Популярное занятие нагружает одну партицию сильнее других.', st: 'mq-kafka' },
    { id: 'idem', w: 5, t: 'At-least-once + идемпотентный потребитель', d: 'Смещение подтверждаем после обработки; дубли отсекает таблица processed_event(consumer, event_id).', why: 'Инцидент 1: пуш «вы записаны» пришёл дважды после ребаланса.', price: 'В каждом потребителе — таблица inbox и проверка.', st: 'mq-delivery' },
    { id: 'outbox', w: 5, t: 'Transactional outbox', d: 'Событие пишем в таблицу outbox в той же транзакции, что и запись; ретранслятор отправляет его в Kafka.', why: 'Инцидент 3: запись есть, а бонусов и пуша нет — сервис упал между коммитом и отправкой.', price: 'Ретранслятор и мониторинг таблицы; отправка может повториться.', st: 'mq-outbox' },
    { id: 'schema', w: 5, t: 'Конверт события и реестр схем', d: 'eventId, type, version, traceId; JSON Schema с совместимостью BACKWARD; ПДн в события не кладём.', why: 'Инцидент 6: в событии переименовали поле — упали старые потребители.', price: 'Ломающие изменения — только новой версией топика.', st: 'mq-events' },
    { id: 'monolith', w: 6, t: 'Модульный монолит + 5 сервисов (ADR-007)', d: 'В ядре — абонементы, запись, платежи. Вынесены: уведомления, партнёрский шлюз, аналитика, бонусы, трансляции.', why: '15 разработчиков в трёх командах; частые общие транзакции абонементов, записи и платежей.', price: 'Ядро релизится целиком; границы модулей держим дисциплиной.', st: 'arch-style' },
    { id: 'owner', w: 6, t: 'Один владелец у каждой таблицы', d: 'Чужие таблицы — только через API владельца или его события; схемы PostgreSQL и проверки ArchUnit.', why: 'Без владельцев модули снова срастаются в «большой ком».', price: 'Иногда нужна копия чужих данных из событий.', st: 'arch-bounded' },
    { id: 'comm', w: 6, t: 'Синхронно, событием или задачей', d: 'Ответ нужен сразу — REST или gRPC; «сообщить остальным» — событие Kafka; «сделай» — очередь RabbitMQ. Снаружи — API-шлюз и BFF.', why: 'Каждому виду общения — свой инструмент.', price: 'Три способа общения — их надо различать в постановках.', st: 'arch-comm' },
    { id: 'saga', w: 6, t: 'Сага покупки с оркестратором', d: '«Продажи» ведут шаги: абонемент → резерв бонусов → оплата → активация; у шагов сроки, у сбоев — компенсации.', why: 'Инцидент 8: деньги списаны, абонемент не активирован. 2PC ПэйПоинт не поддерживает.', price: 'Клиент видит промежуточное «оплата проверяется».', st: 'arch-saga' },
    { id: 'docs', w: 6, t: 'Сценарии качества и ADR', d: '«Быстро» → «400 записей/с, p95 ≤ 300 мс»; решения записаны в ADR-007, 008, 009.', why: 'Без чисел архитектуру не выбрать и не проверить.', price: 'Время на документы — окупается на комитете.', st: 'arch-docs' },
    { id: 'bulk', w: 7, t: 'Переборка, таймауты, предохранитель', d: 'Свой пул для 1С, SMS, ПэйПоинта; предохранитель размыкает цепь; в пик отключаем рекомендации (деградация).', why: 'Инцидент 4: 1С зависла — запись легла на 40 минут.', price: 'Больше настроек и пулов, которые надо подбирать.', st: 'rel-patterns' },
    { id: 'scale', w: 7, t: '6 экземпляров ядра + кэш Redis', d: 'Ядро без состояния за балансировщиком; cache-aside, TTL 30 с + сброс по событию; PgBouncer; решение о записи — в базе.', why: 'Пик 20 000 человек за 5 минут — около 400 записей в секунду.', price: 'Кэш отстаёт до 30 с — места на экране приблизительные.', st: 'rel-scale' },
    { id: 'cqrs', w: 7, t: 'CQRS: отчёты в ClickHouse', d: 'Модель чтения собирается из событий Kafka и отстаёт до минуты; «Мои записи» читаем из ядра.', why: 'Тяжёлые отчёты не должны тормозить запись.', price: 'Отставание и пересборка модели при ошибках.', st: 'rel-cqrs' },
    { id: 'slo', w: 7, t: 'SLO и наблюдаемость', d: 'Запись: 99,9 % в месяц, p95 ≤ 300 мс; логи, метрики, трассировки с одним traceId; алерты на симптомы.', why: 'Узнать о сбое раньше клиентов и иметь правило для релизов.', price: 'Сгорел бюджет ошибок — рискованные релизы ждут.', st: 'rel-observe' },
    { id: 'deploy', w: 7, t: 'Canary, флаги, expand–contract', d: '5 % → 50 % → 100 % с автооткатом по SLO; бонусы включаем по клубам; без релизов в воскресенье 18:00–22:00.', why: 'Релиз — частая причина аварий.', price: 'Выкатка дольше; старые флаги надо убирать.', st: 'rel-deploy' },
    { id: 'online', w: 8, t: 'Онлайн-тренировки: внешний видеосервис', d: 'Сервис «Трансляции» + внешний видеосервис + CDN; чат по WebSocket; события эфира в Kafka.', why: '2 000 зрителей × 3 Мбит/с ≈ 6 Гбит/с — не для наших серверов.', price: 'Зависимость от поставщика и плата за минуты.', st: 'sd-design' },
    { id: 'night', w: 8, t: 'Ночь инцидентов 2.0', d: 'Сбои сезона: дубли, порядок, потерянные события, отставание, сломанная схема, зависшая сага.', why: 'Решения проверяются отказами.', price: 'Дежурства и постмортемы.', st: 'sd-incidents' }
  ];
  const PAINS = [
    { v: 'all', t: 'Все решения', ids: [] },
    { v: 'peak', t: 'Пик 20 000 за 5 минут', ids: ['scale', 'bulk', 'cqrs', 'slo'], chain: 'Экземпляры ядра без состояния и кэш держат чтение и запись (неделя 7) → тяжёлые отчёты ушли в ClickHouse и не мешают (CQRS) → если что-то зависло, переборка и деградация сохраняют запись → SLO показывает, держим ли мы обещание.' },
    { v: 'six', t: '6 потребителей события', ids: ['kafka', 'key', 'idem', 'schema', 'comm'], chain: 'Одно событие в Kafka вместо шести вызовов (неделя 5) → ключ партиции сохраняет порядок событий занятия → идемпотентные потребители переживают дубли → реестр схем не даёт сломать старых читателей → правило «синхронно / событие / задача» (неделя 6).' },
    { v: 'money', t: 'Не терять деньги и бонусы', ids: ['outbox', 'idem', 'saga', 'owner'], chain: 'Outbox не теряет событие между базой и Kafka → идемпотентный потребитель не начисляет дважды → сага с компенсациями не оставляет клиента «без денег и без абонемента» → у бонусного счёта один владелец — сервис «Бонусы».' },
    { v: 'onec', t: 'Зависла 1С', ids: ['bulk', 'comm', 'kafka', 'slo'], chain: 'Выгрузка в 1С идёт событием, а не синхронным вызовом из записи → свой пул, таймаут и предохранитель изолируют зависание → алерт на симптом скажет дежурному раньше клиентов.' },
    { v: 'release', t: 'Релизы без риска', ids: ['deploy', 'slo', 'schema'], chain: 'Canary с автооткатом по SLO и флаги по клубам → бюджет ошибок решает, можно ли рисковать → совместимость схем не ломает потребителей при релизе.' },
    { v: 'team', t: '15 разработчиков', ids: ['monolith', 'owner', 'docs', 'online'], chain: 'Модульный монолит для общих транзакций и пять сервисов там, где есть причина → один владелец у таблицы → решения записаны в ADR, чтобы три команды не спорили заново.' }
  ];
  const howMap = {
    id: 'how-map', covers: ['blitz', 'trace', 'summary'], title: 'Как это работает: карта решений сезона 2', free: true, noReset: true,
    simple: {
      icon: '🗺️',
      plain: 'За четыре недели «Пульс» принял почти двадцать решений. По отдельности их не защитить: комитет спрашивает про боль бизнеса, а ответ — это цепочка решений из разных недель.',
      analogy: 'Как план подготовки к марафону: интервалы, длинные пробежки, сон, питание. Спросят «почему вы не устанете на 30-м километре?» — ответ не одно упражнение, а связка из нескольких.',
      tech: '<b>Журнал решений</b> (decision log): каждое решение — с причиной (факт, инцидент), ценой и ссылкой на ADR. <b>Трассируемость</b>: от боли бизнеса к цепочке решений и обратно. На защите показывают, что ни одна боль не осталась без ответа и что цена каждого решения известна.'
    },
    lead: ui.brief({
      situation: 'Через два часа комитет. Вера: «Давайте разложим всё, что приняли за сезон, на одну доску. Тогда на любой вопрос вы покажете не одно решение, а цепочку — и где мы её разбирали».',
      todo: [
        'Нажмите на любое решение — ниже появится, что это, почему его приняли и чем за него платим. Кнопка «Открыть тренировку» перенесёт туда, где его разбирали.',
        'Переключайте боль «Пульса» сверху — подсветится цепочка решений из разных недель, которая её закрывает.'
      ],
      look: 'Четыре колонки — четыре недели сезона. Подсвеченные карточки — решения, которые закрывают выбранную боль; остальные тускнеют. Под картой — цепочка словами: так её и говорят на комитете.'
    }),
    render(el) {
      el.classList.add('sdf-root');
      let pain = 'all', sel = 'outbox';
      el.innerHTML = `<div class="stack" style="gap:14px">
        <div><div class="eyebrow" style="margin-bottom:6px">Боль «Пульса»</div>${ui.seg('pain', PAINS.map(p => ({ v: p.v, t: p.t })), pain, 'accent')}</div>
        <div class="sdf-map" data-sdf-map></div>
        <div data-sdf-chain></div>
        <div data-sdf-det></div>
      </div>`;
      function draw() {
        const P = PAINS.find(p => p.v === pain), hot = new Set(P.ids);
        TR.$('[data-sdf-map]', el).innerHTML = WEEKS.map(w => `<div class="sdf-col"><div class="eyebrow">${esc(w.t)}</div>${NODES.filter(n => n.w === w.n).map(n => {
          const c = pain === 'all' ? '' : hot.has(n.id) ? 'hot' : 'dim';
          const def = TR.stageById(n.st);
          return `<button type="button" class="sdf-node ${c}" data-sdf-node="${n.id}" aria-pressed="${n.id === sel}">${esc(n.t)}<span class="st">${def ? esc(def.slot + ' · ' + def.title) : 'тренировка готовится'}</span></button>`;
        }).join('')}</div>`).join('');
        TR.$('[data-sdf-chain]', el).innerHTML = pain === 'all' ? '' : ui.note('ok', 'Цепочка для комитета: ' + P.t, P.chain);
        const n = NODES.find(x => x.id === sel), def = TR.stageById(n.st);
        TR.$('[data-sdf-det]', el).innerHTML = `<div class="sdf-box"><div><div class="eyebrow">${esc(WEEKS.find(w => w.n === n.w).t)}</div><b style="font-size:16px">${esc(n.t)}</b></div>
          <p style="margin:0">${esc(n.d)}</p>
          <div class="grid2"><div class="card flat"><div class="eyebrow">Почему приняли</div><div>${esc(n.why)}</div></div><div class="card flat"><div class="eyebrow">Чем платим</div><div>${esc(n.price)}</div></div></div>
          <div class="row">${def ? `<button type="button" class="btn sm" data-sdf-go="${esc(n.st)}">Открыть тренировку «${esc(def.title)}» →</button>` : '<span class="small dim">Тренировка, где это разбирают, ещё готовится.</span>'}</div></div>`;
      }
      TR.on(el, 'click', '[data-sdf-node]', (e, b) => { sel = b.dataset.sdfNode; draw(); });
      TR.on(el, 'click', '[data-sdf-go]', (e, b) => { if (TR.stageById(b.dataset.sdfGo)) TR.go(b.dataset.sdfGo); });
      ui.onSeg(el, (nm, v) => { if (nm === 'pain') { pain = v; const P = PAINS.find(p => p.v === v); if (P.ids.length && !P.ids.includes(sel)) sel = P.ids[0]; draw(); } });
      draw();
    }
  };

  // =====================================================================
  // Теория 2. Как отвечать комитету: факт → риск → решение → цена
  // =====================================================================
